+fn op_on_consts(op: koopa::ir::BinaryOp, lhs: i32, rhs: i32) -> i32 {
+    match op {
+        koopa::ir::BinaryOp::NotEq => (lhs != rhs) as i32,
+        koopa::ir::BinaryOp::Eq => (lhs == rhs) as i32,
+        koopa::ir::BinaryOp::Gt => (lhs > rhs) as i32,
+        koopa::ir::BinaryOp::Lt => (lhs < rhs) as i32,
+        koopa::ir::BinaryOp::Ge => (lhs >= rhs) as i32,
+        koopa::ir::BinaryOp::Le => (lhs <= rhs) as i32,
