//! Build a single component into Koopa IR.

use crate::ast_def::statements::*;
use koopa::ir::{builder_traits::*, Program};

use super::{
    build_expressions::{IRExpBuildResult, IRExpBuildable, IRLValBuildResult},
    create_new_block, create_new_local_value, insert_basic_blocks, insert_local_instructions,
    IRBuildResult, IRBuildable, MyIRGeneratorInfo,
};

fn create_i32_const(
    value: i32,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> koopa::ir::Value {
    create_new_local_value(program, my_ir_generator_info).integer(value)
}

impl IRBuildable for Stmt {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        match &self {
            Stmt::UnmatchedStmt(stmt) => stmt.build(program, my_ir_generator_info),
            Stmt::MatchedStmt(stmt) => stmt.build(program, my_ir_generator_info),
        }
    }
}

impl IRBuildable for UnmatchedStmt {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        self.default.build(program, my_ir_generator_info)
    }
}

impl IRBuildable for MatchedStmt {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        self.default.build(program, my_ir_generator_info)
    }
}

impl IRBuildable for BasicStmt {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        match self {
            BasicStmt::AssignStmt(lval, exp) => {
                let dest = match lval.build(program, my_ir_generator_info)? {
                    IRLValBuildResult::Addr(addr) => addr,
                    _ => return Err(format!("Assignment target must be an lvalue: {:?}", lval)),
                };
                let value = match exp.build(program, my_ir_generator_info)? {
                    IRExpBuildResult::Const(int) => {
                        create_i32_const(int, program, my_ir_generator_info)
                    }
                    IRExpBuildResult::Value(value) => value,
                };
                let store = create_new_local_value(program, my_ir_generator_info).store(value, dest);
                insert_local_instructions(program, my_ir_generator_info, [store]);
                Ok(IRBuildResult::OK)
            }
            BasicStmt::Exp(exp) => {
                if let Some(exp) = exp {
                    exp.build(program, my_ir_generator_info)?;
                }
                Ok(IRBuildResult::OK)
            }
            BasicStmt::Block(block) => {
                my_ir_generator_info.symbol_tables.add_new_table();
                block.build(program, my_ir_generator_info)
            }
            BasicStmt::IfStmt(cond, then_stmt, else_stmt) => {
                let cond_result = cond.build(program, my_ir_generator_info)?;
                match (cond_result, else_stmt.as_ref()) {
                    (IRExpBuildResult::Const(int), None) => {
                        if int == 0 {
                            Ok(IRBuildResult::OK)
                        } else {
                            then_stmt.build(program, my_ir_generator_info)
                        }
                    }
                    (IRExpBuildResult::Const(int), Some(else_stmt)) => {
                        if int != 0 {
                            then_stmt.build(program, my_ir_generator_info)
                        } else {
                            else_stmt.build(program, my_ir_generator_info)
                        }
                    }
                    (cond_result, None) => {
                        let cond_value = match cond_result {
                            IRExpBuildResult::Const(int) => {
                                create_i32_const(int, program, my_ir_generator_info)
                            }
                            IRExpBuildResult::Value(value) => value,
                        };
                        let then_bb = create_new_block(program, my_ir_generator_info, "if_then");
                        let end_bb = create_new_block(program, my_ir_generator_info, "if_end");
                        insert_basic_blocks(program, my_ir_generator_info, [then_bb, end_bb]);

                        let br = create_new_local_value(program, my_ir_generator_info)
                            .branch(cond_value, then_bb, end_bb);
                        insert_local_instructions(program, my_ir_generator_info, [br]);

                        my_ir_generator_info.curr_block = Some(then_bb);
                        let then_result = then_stmt.build(program, my_ir_generator_info)?;
                        if let IRBuildResult::OK = then_result {
                            let jump =
                                create_new_local_value(program, my_ir_generator_info).jump(end_bb);
                            insert_local_instructions(program, my_ir_generator_info, [jump]);
                        }

                        my_ir_generator_info.curr_block = Some(end_bb);
                        Ok(IRBuildResult::OK)
                    }
                    (cond_result, Some(else_stmt)) => {
                        let cond_value = match cond_result {
                            IRExpBuildResult::Const(int) => {
                                create_i32_const(int, program, my_ir_generator_info)
                            }
                            IRExpBuildResult::Value(value) => value,
                        };
                        let then_bb = create_new_block(program, my_ir_generator_info, "if_then");
                        let else_bb = create_new_block(program, my_ir_generator_info, "if_else");
                        let end_bb = create_new_block(program, my_ir_generator_info, "if_end");
                        insert_basic_blocks(program, my_ir_generator_info, [then_bb, else_bb, end_bb]);

                        let br = create_new_local_value(program, my_ir_generator_info)
                            .branch(cond_value, then_bb, else_bb);
                        insert_local_instructions(program, my_ir_generator_info, [br]);

                        my_ir_generator_info.curr_block = Some(then_bb);
                        let then_result = then_stmt.build(program, my_ir_generator_info)?;
                        if let IRBuildResult::OK = then_result {
                            let jump =
                                create_new_local_value(program, my_ir_generator_info).jump(end_bb);
                            insert_local_instructions(program, my_ir_generator_info, [jump]);
                        }

                        my_ir_generator_info.curr_block = Some(else_bb);
                        let else_result = else_stmt.build(program, my_ir_generator_info)?;
                        if let IRBuildResult::OK = else_result {
                            let jump =
                                create_new_local_value(program, my_ir_generator_info).jump(end_bb);
                            insert_local_instructions(program, my_ir_generator_info, [jump]);
                        }

                        if matches!(then_result, IRBuildResult::EARLYSTOPPING)
                            && matches!(else_result, IRBuildResult::EARLYSTOPPING)
                        {
                            Ok(IRBuildResult::EARLYSTOPPING)
                        } else {
                            my_ir_generator_info.curr_block = Some(end_bb);
                            Ok(IRBuildResult::OK)
                        }
                    }
                }
            }
            BasicStmt::WhileStmt(cond, body) => {
                let cond_bb = create_new_block(program, my_ir_generator_info, "while_cond");
                let body_bb = create_new_block(program, my_ir_generator_info, "while_body");
                let end_bb = create_new_block(program, my_ir_generator_info, "while_end");
                insert_basic_blocks(program, my_ir_generator_info, [cond_bb, body_bb, end_bb]);

                let jump_to_cond =
                    create_new_local_value(program, my_ir_generator_info).jump(cond_bb);
                insert_local_instructions(program, my_ir_generator_info, [jump_to_cond]);

                my_ir_generator_info.curr_block = Some(cond_bb);
                let cond_value = match cond.build(program, my_ir_generator_info)? {
                    IRExpBuildResult::Const(int) => {
                        create_i32_const(int, program, my_ir_generator_info)
                    }
                    IRExpBuildResult::Value(value) => value,
                };
                let br = create_new_local_value(program, my_ir_generator_info)
                    .branch(cond_value, body_bb, end_bb);
                insert_local_instructions(program, my_ir_generator_info, [br]);

                my_ir_generator_info.break_tgt_blocks.push(end_bb);
                my_ir_generator_info.continue_tgt_blocks.push(cond_bb);

                my_ir_generator_info.curr_block = Some(body_bb);
                let body_result = body.build(program, my_ir_generator_info)?;
                if let IRBuildResult::OK = body_result {
                    let jump_back =
                        create_new_local_value(program, my_ir_generator_info).jump(cond_bb);
                    insert_local_instructions(program, my_ir_generator_info, [jump_back]);
                }

                my_ir_generator_info.break_tgt_blocks.pop();
                my_ir_generator_info.continue_tgt_blocks.pop();
                my_ir_generator_info.curr_block = Some(end_bb);
                Ok(IRBuildResult::OK)
            }
            BasicStmt::BreakStmt => {
                let target = *my_ir_generator_info
                    .break_tgt_blocks
                    .last()
                    .ok_or_else(|| "break used outside of loop".to_string())?;
                let jump = create_new_local_value(program, my_ir_generator_info).jump(target);
                insert_local_instructions(program, my_ir_generator_info, [jump]);
                Ok(IRBuildResult::EARLYSTOPPING)
            }
            BasicStmt::ContinueStmt => {
                let target = *my_ir_generator_info
                    .continue_tgt_blocks
                    .last()
                    .ok_or_else(|| "continue used outside of loop".to_string())?;
                let jump = create_new_local_value(program, my_ir_generator_info).jump(target);
                insert_local_instructions(program, my_ir_generator_info, [jump]);
                Ok(IRBuildResult::EARLYSTOPPING)
            }
            BasicStmt::ReturnStmt(exp) => {
                let ret = match exp {
                    Some(exp) => {
                        let value = match exp.build(program, my_ir_generator_info)? {
                            IRExpBuildResult::Const(int) => {
                                create_i32_const(int, program, my_ir_generator_info)
                            }
                            IRExpBuildResult::Value(value) => value,
                        };
                        create_new_local_value(program, my_ir_generator_info).ret(Some(value))
                    }
                    None => create_new_local_value(program, my_ir_generator_info).ret(None),
                };
                insert_local_instructions(program, my_ir_generator_info, [ret]);
                Ok(IRBuildResult::EARLYSTOPPING)
            }
        }
    }
}

