   574	                        my_ir_generator_info,
   575	                    )?,
   576	                    (true, None) => create_zero_init_value(ty.clone(), program, my_ir_generator_info),
   577	                    (false, Some(init_val)) => build_array_init_value(
   578	                        init_val,
   579	                        &shape,
   580	                        true,
   581	                        program,
   582	                        my_ir_generator_info,
   583	                    )?,
   584	                    (false, None) => create_zero_init_value(ty.clone(), program, my_ir_generator_info),
   585	                };
   586	                let global = program.new_value().global_alloc(init);
   587	                program.set_value_name(global, Some(format!("@{}", ident.content)));
   588	                my_ir_generator_info.symbol_tables.insert(
   589	                    ident.content.clone(),
   590	                    SymbolTableEntry::Variable(ty.kind().clone(), global),
   591	                );
   592	                continue;
   593	            }
   594	
   595	            let alloc = create_new_local_value(program, my_ir_generator_info).alloc(ty.clone());
   596	            program
   597	                .func_mut(my_ir_generator_info.curr_func.unwrap())
   598	                .dfg_mut()
   599	                .set_value_name(alloc, Some(format!("@{}", ident.content)));
   600	            insert_local_instructions(program, my_ir_generator_info, [alloc]);
   601	            my_ir_generator_info.symbol_tables.insert(
   602	                ident.content.clone(),
   603	                SymbolTableEntry::Variable(ty.kind().clone(), alloc),
   604	            );
   605	
   606	            if let Some(init_val) = init_val {
   607	                if shape.is_empty() {
   608	                    let value =
   609	                        build_scalar_init_value(init_val, false, program, my_ir_generator_info)?;
   610	                    let store = create_new_local_value(program, my_ir_generator_info).store(value, alloc);
   611	                    insert_local_instructions(program, my_ir_generator_info, [store]);
   612	                } else {
   613	                    let init =
   614	                        build_array_init_value(init_val, &shape, false, program, my_ir_generator_info)?;
   615	                    aggregate_to_store_insts(init, alloc, program, my_ir_generator_info)?;
   616	                }
   617	            }
   618	        }
   619	        Ok(IRBuildResult::OK)
   620	    }
   621	}
